import java.io.*;import java.nio.file.*;import java.util.logging.Logger;import org.bukkit.plugin.Plugin;import ru.rooyzee.elytrixtalisman.patch.RecoveryGuard;
public class RecoveryTest {
 static class P implements Plugin {final File f;P(File f){this.f=f;}public File getDataFolder(){return f;}public Logger getLogger(){return Logger.getLogger("recovery-test");}}
 static void check(boolean v){if(!v)throw new AssertionError();}
 public static void main(String[]args)throws Exception{Path d=Files.createTempDirectory("tal-recovery");try{P p=new P(d.toFile());check(RecoveryGuard.canStart(p,false,false));check(!RecoveryGuard.canStart(p,true,false));check(!RecoveryGuard.canStart(p,false,true));Files.createDirectories(d.resolve("restore"));Path s=d.resolve("restore/pending.schem"),m=d.resolve("restore/pending.yml");Files.writeString(s,"backup");check(!RecoveryGuard.canStart(p,false,false));try{RecoveryGuard.requireSaved(p);throw new AssertionError();}catch(IOException expected){}Files.writeString(m,"world: world\nx: 4\ny: -12\nz: 2\n");RecoveryGuard.requireSaved(p);Files.writeString(m,"world: world\nx: 4\n");try{RecoveryGuard.requireSaved(p);throw new AssertionError();}catch(IOException expected){}System.out.println("Pending recovery protection and metadata checks OK");}finally{Files.walk(d).sorted(java.util.Comparator.reverseOrder()).forEach(x->{try{Files.deleteIfExists(x);}catch(IOException e){throw new RuntimeException(e);}});}}
}
